import React, { useState, useEffect } from 'react';
import { DRINK_BRANDS, QUANTITY_TYPES, BEVERAGES } from '../data/constants';

const Table = ({ tableId }) => {
    const [items, setItems] = useState(() => {
        const tableKey = `table_${tableId}`;
        const savedData = localStorage.getItem(tableKey);
        return savedData ? JSON.parse(savedData) : {
            drinks: [],
            beverages: [],
            food: [],
            others: []
        };
    });

    const [showModal, setShowModal] = useState(false);
    // Remove this line
    // const [showDrinkForm, setShowDrinkForm] = useState(false);
    const [showBeverageForm, setShowBeverageForm] = useState(false);
    const [showFoodForm, setShowFoodForm] = useState(false);
    const [showOthersForm, setShowOthersForm] = useState(false);

    useEffect(() => {
        // Load table data when component mounts or tableId changes
        const tableKey = `table_${tableId}`;
        const savedData = localStorage.getItem(tableKey);
        if (savedData) {
            setItems(JSON.parse(savedData));
        }
    }, [tableId]);

    const calculateSectionTotal = (section) => {
        const tableKey = `table_${tableId}`;
        const savedData = localStorage.getItem(tableKey);
        const tableItems = savedData ? JSON.parse(savedData) : items;
        
        if (!tableItems || !tableItems[section]) return 0;
        
        return tableItems[section].reduce((total, item) => {
            return total + ((parseFloat(item.price) || 0) * (parseInt(item.quantity) || 0));
        }, 0);
    };

    const calculateGrandTotal = () => {
        const tableKey = `table_${tableId}`;
        const savedData = localStorage.getItem(tableKey);
        const tableItems = savedData ? JSON.parse(savedData) : items;
        
        if (!tableItems) return 0;

        return Object.keys(tableItems).reduce((total, section) => {
            if (!tableItems[section]) return total;
            return total + tableItems[section].reduce((sectionTotal, item) => {
                return sectionTotal + ((parseFloat(item.price) || 0) * (parseInt(item.quantity) || 0));
            }, 0);
        }, 0);
    };

    const addItem = (section, item) => {
        const newItems = {
            ...items,
            [section]: [...items[section], item]
        };
        setItems(newItems);
        // Update localStorage after state change
        const tableKey = `table_${tableId}`;
        localStorage.setItem(tableKey, JSON.stringify(newItems));
    };

    const handleConfirmation = () => {
        const tableKey = `table_${tableId}`;
        localStorage.removeItem(tableKey);
        setItems({
            drinks: [],
            beverages: [],
            food: [],
            others: []
        });
        setShowModal(false);
    };

    const handlePayment = () => {
        setShowModal(true);
    };

    const closeModal = () => {
        setShowModal(false);
    };

    const renderItemsList = (sectionItems, sectionName) => {
        return sectionItems.length > 0 && (
            <div className="summary-section">
                <h4>{sectionName}</h4>
                {sectionItems.map((item, index) => (
                    <div key={index} className="summary-item">
                        {item.brand || item.type || item.name} - 
                        {item.quantity} x ₹{item.price} = ₹{item.price * item.quantity}
                    </div>
                ))}
                <div className="section-total">
                    Total: ₹{calculateSectionTotal(sectionName.toLowerCase())}
                </div>
            </div>
        );
    };

    return (
        <div className="table-container">
            <h2>Table {tableId}</h2>
            
            {/* Drinks Section */}
            <section>
                <div className="section-header">
                    <h3>Drinks</h3>
                </div>
                <form onSubmit={(e) => {
                    e.preventDefault();
                    addItem('drinks', {
                        brand: e.target.brand.value,
                        quantity: parseInt(e.target.quantity.value),
                        price: parseFloat(e.target.price.value)
                    });
                    e.target.reset();
                }}>
                    <select name="brand" required>
                        {DRINK_BRANDS.map(brand => (
                            <option key={brand} value={brand}>{brand}</option>
                        ))}
                    </select>
                    <input type="number" name="quantity" placeholder="Qty" required />
                    <input type="number" name="price" placeholder="₹" step="0.01" required />
                    <button type="submit">Add</button>
                </form>
                <p>Total: ₹{calculateSectionTotal('drinks').toFixed(2)}</p>
            </section>

            {/* Beverages Section */}
            <section>
                <h3>Beverages</h3>
                <form onSubmit={(e) => {
                    e.preventDefault();
                    addItem('beverages', {
                        type: e.target.type.value,
                        quantity: parseInt(e.target.quantity.value),
                        price: parseFloat(e.target.price.value)
                    });
                    e.target.reset();
                }}>
                    <select name="type" required>
                        {BEVERAGES.map(beverage => (
                            <option key={beverage} value={beverage}>{beverage}</option>
                        ))}
                    </select>
                    <input type="number" name="quantity" placeholder="Quantity" required />
                    <input type="number" name="price" placeholder="Price" step="0.01" required />
                    <button type="submit">Add Beverage</button>
                </form>
                // Update the section totals display in JSX
                <p>Section Total: ₹{calculateSectionTotal('beverages').toFixed(2)}</p>
                
                // Update the food section total
                <p>Section Total: ₹{calculateSectionTotal('food').toFixed(2)}</p>
                
                // Update the others section total
                <p>Section Total: ₹{calculateSectionTotal('others').toFixed(2)}</p>
            </section>

            {/* Food Section */}
            <section>
                <h3>Food</h3>
                <form onSubmit={(e) => {
                    e.preventDefault();
                    addItem('food', {
                        name: e.target.name.value,
                        quantity: parseInt(e.target.quantity.value),
                        price: parseFloat(e.target.price.value)
                    });
                    e.target.reset();
                }}>
                    <input type="text" name="name" placeholder="Food Item" required />
                    <input type="number" name="quantity" placeholder="Quantity" required />
                    <input type="number" name="price" placeholder="Price" step="0.01" required />
                    <button type="submit">Add Food</button>
                </form>
                <p>Section Total: ${calculateSectionTotal('food')}</p>
            </section>

            {/* Others Section */}
            <section>
                <h3>Others</h3>
                <form onSubmit={(e) => {
                    e.preventDefault();
                    addItem('others', {
                        name: e.target.name.value,
                        quantity: parseInt(e.target.quantity.value),
                        price: parseFloat(e.target.price.value)
                    });
                    e.target.reset();
                }}>
                    <input type="text" name="name" placeholder="Item Name" required />
                    <input type="number" name="quantity" placeholder="Quantity" required />
                    <input type="number" name="price" placeholder="Price" step="0.01" required />
                    <button type="submit">Add Item</button>
                </form>
                <p>Section Total: ${calculateSectionTotal('others')}</p>
            </section>

            <div className="totals">
                <h3>Grand Total: ₹{calculateGrandTotal().toFixed(2)}</h3>
                <button onClick={handlePayment}>Pay Now</button>
            </div>
            
            {showModal && (
                <div className="modal-overlay">
                    <div className="modal-content">
                        <h3>Purchase Summary - Table {tableId}</h3>
                        {renderItemsList(items.drinks, "Drinks")}
                        {renderItemsList(items.beverages, "Beverages")}
                        {renderItemsList(items.food, "Food")}
                        {renderItemsList(items.others, "Others")}
                        <div className="final-total">
                            Final Total: ₹{calculateGrandTotal().toFixed(2)}
                        </div>
                        <div className="modal-buttons">
                            <button onClick={handleConfirmation}>Confirm Payment</button>
                            <button onClick={closeModal}>Close</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Table;